import { el } from './dom.ts';
import { CATEGORIES, type Category } from '../shared/coins.ts';
import { t } from './i18n.ts';

/**
 * Which kind of instrument the coin picker lists (shared/coins.ts `Category`): the coins the exchanges trade as crypto tokens, and the
 * tokenized instruments they list beside them (a fiat pair, a stock or fund, a commodity such as gold, a stock-market index). The choice is a
 * view setting of this browser, not the page's data: it is kept in `lmf.coin.category` and read by the coin list's buttons, so the next visit
 * opens on the same kind.
 */
const KEY = 'lmf.coin.category';

/** The English names are the keys of the packs; each is translated once, when this module loads. */
const LABELS: Readonly<Record<Category, string>> = {
  crypto: t('Crypto'), forex: t('Forex'), stocks: t('Stocks'), commodities: t('Commodities'), indices: t('Indices'),
};

/** "Crypto", "Crypto" in the page's language. */
export const categoryLabel = (category: Category): string => LABELS[category];

/** The kind this browser was last left on, or `fallback` (the coin on the page) until one is chosen. */
export function readCategory(fallback: Category = 'crypto'): Category {
  try {
    const saved = localStorage.getItem(KEY);
    return CATEGORIES.includes(saved as Category) ? saved as Category : fallback;
  } catch { return fallback; }
}

/** Keep a kind for this browser; a page without storage (a private window that refuses it) still filters this time. */
export function saveCategory(category: Category): void {
  try { localStorage.setItem(KEY, category); } catch { /* nothing is kept between pages, and the list still filters */ }
}

/**
 * The five kind buttons, shared inside the coin picker: one is on at a time, and the caller's `onPick` filters its list. `sync` moves the lit
 * button when the list's own choice changed (read back from the dialog's state).
 */
export function categoryButtons(onPick: (category: Category) => void, category: Category = readCategory()): { root: HTMLElement; sync(next?: Category): void } {
  const root = el('div', { class: 'seg categories', role: 'group' });
  root.setAttribute('aria-label', t('Coin category'));
  const buttons = new Map<Category, HTMLButtonElement>();
  for (const c of CATEGORIES) {
    const button = el('button', { type: 'button', class: 'category', textContent: categoryLabel(c), tip: t('Filter the list: {category}', { category: categoryLabel(c) }), onclick: () => onPick(c) });
    buttons.set(c, button);
    root.append(button);
  }
  const sync = (next = category): void => {
    category = next;
    for (const [c, button] of buttons) {
      const on = c === category;
      button.classList.toggle('on', on);
      button.setAttribute('aria-pressed', String(on));
    }
  };
  sync();
  return { root, sync };
}
